def Tim(A,k):
    d=0
    c=len(A)-1
    while d<=c:
        g=(d+c)//2
        if A[g]==k:
            return g
        elif A[g]<k:
            d=g+1
        else:
            c=g-1
    return -1
[/pre]
hoặc bằng C++:
[pre]
int Tim(int A[], int k) {
    int d=0;
    int c=sizeof A / sizeof(int)-1;
    while (d<=c) {
        int g=(d+c)/2;
        if (A[g]==k){
            return g;
        }
        else if (A[g]<k){
            d=g+1;
        }
        else{
            c=g-1;
        }
    }
    return -1;
}

[/pre]
